begin;
select plan(20);
insert into auth.users(id) values ('53000000-0000-4000-8000-000000000001');
insert into auth.sessions(id,user_id) values ('63000000-0000-4000-8000-000000000001','53000000-0000-4000-8000-000000000001');
insert into public.staff_members(user_id,active) values ('53000000-0000-4000-8000-000000000001',true);
insert into public.animals(id,name,species,sex,size,approximate_age) values ('03000000-0000-4000-8000-000000000001','Photo test','dog','female','small','1');
create temporary table jobs(n int,j jsonb);grant all on jobs to service_role;
create temporary table leases(j jsonb);grant all on leases to service_role;
set local role service_role;
insert into jobs select 1,public.reserve_photo_upload('03000000-0000-4000-8000-000000000001','53000000-0000-4000-8000-000000000001','63000000-0000-4000-8000-000000000001',repeat('a',32),repeat('a',64));
select is((select j->>'state' from jobs where n=1),'pending','job before storage');
select throws_ok(format('select public.finalize_photo_upload(%L,%L,%L,%L)',(select j->>'id' from jobs where n=1),'53000000-0000-4000-8000-000000000001','63000000-0000-4000-8000-000000000001',(select j->>'upload_token' from jobs where n=1)),'22023','invalid_job','pending cannot attach');
select public.validate_photo_upload((select (j->>'id')::uuid from jobs where n=1),(select (j->>'upload_token')::uuid from jobs where n=1),'image/png',100);
select is(public.finalize_photo_upload((select (j->>'id')::uuid from jobs where n=1),'53000000-0000-4000-8000-000000000001','63000000-0000-4000-8000-000000000001',(select (j->>'upload_token')::uuid from jobs where n=1))->>'state','attached','validated job attaches');
insert into jobs select 2,public.reserve_photo_upload('03000000-0000-4000-8000-000000000001','53000000-0000-4000-8000-000000000001','63000000-0000-4000-8000-000000000001',repeat('b',32),repeat('b',64));
select public.validate_photo_upload((select (j->>'id')::uuid from jobs where n=2),(select (j->>'upload_token')::uuid from jobs where n=2),'image/png',100);
select public.finalize_photo_upload((select (j->>'id')::uuid from jobs where n=2),'53000000-0000-4000-8000-000000000001','63000000-0000-4000-8000-000000000001',(select (j->>'upload_token')::uuid from jobs where n=2));
select is((select state from public.photo_upload_jobs where id=(select (j->>'id')::uuid from jobs where n=1)),'cleanup_needed','superseded queued');
select public.finalize_photo_upload((select (j->>'id')::uuid from jobs where n=1),'53000000-0000-4000-8000-000000000001','63000000-0000-4000-8000-000000000001',(select (j->>'upload_token')::uuid from jobs where n=1));
select is((select primary_photo_id::text from public.animals where id='03000000-0000-4000-8000-000000000001'),(select j->>'id' from jobs where n=2),'replay never reactivates old photo');
select throws_ok($$select public.reserve_photo_upload('03000000-0000-4000-8000-000000000001','53000000-0000-4000-8000-000000000001','63000000-0000-4000-8000-000000000001',repeat('a',32),repeat('c',64))$$,'PT409','operation_conflict','payload conflict');
insert into leases select public.claim_photo_cleanup();
select is((select jsonb_array_length(j) from leases),1,'cleanup claims superseded only');
select is(jsonb_array_length(public.claim_photo_cleanup()),0,'second worker cannot claim active lease');
select public.complete_photo_cleanup((select (j->0->>'job_id')::uuid from leases),(select (j->0->>'lease_token')::uuid from leases),false);
select is((select attempts from public.photo_cleanup_queue where job_id=(select (j->>'id')::uuid from jobs where n=1)),1,'storage failure persists retry');
select is(jsonb_array_length(public.claim_photo_cleanup()),0,'backoff blocks immediate retry');
reset role;
update public.photo_cleanup_queue set next_attempt_at=now()-interval '1 second' where job_id=(select (j->>'id')::uuid from jobs where n=1);
set local role service_role;
insert into leases select public.claim_photo_cleanup();
select public.complete_photo_cleanup((select (j->>'id')::uuid from jobs where n=1),gen_random_uuid(),true);
select is((select state from public.photo_upload_jobs where id=(select (j->>'id')::uuid from jobs where n=1)),'cleanup_needed','wrong lease never completes deletion');
select public.complete_photo_cleanup((select (j->>'id')::uuid from jobs where n=1),(select (j->0->>'lease_token')::uuid from leases order by (j->0->>'lease_token') limit 1),true);
-- Complete with both recorded tokens; only the current one can change the job.
select public.complete_photo_cleanup((select (j->>'id')::uuid from jobs where n=1),(j->0->>'lease_token')::uuid,true) from leases;
select is((select state from public.photo_upload_jobs where id=(select (j->>'id')::uuid from jobs where n=1)),'cleaned','successful retry reaches terminal state');
select is((select primary_photo_id::text from public.animals where id='03000000-0000-4000-8000-000000000001'),(select j->>'id' from jobs where n=2),'cleanup preserves current photo');
insert into jobs select 3,public.reserve_photo_upload('03000000-0000-4000-8000-000000000001','53000000-0000-4000-8000-000000000001','63000000-0000-4000-8000-000000000001',repeat('d',32),repeat('d',64));
reset role;
update public.photo_upload_jobs set created_at=now()-interval '16 minutes',upload_expires_at=now()-interval '1 minute' where id=(select (j->>'id')::uuid from jobs where n=3);
set local role service_role;
select is(jsonb_array_length(public.claim_photo_cleanup()),1,'stale pending job terminalized before delete');
reset role;
select is((select schedule from cron.job where jobname='animal-photo-cleanup'),'*/15 * * * *','cleanup scheduled each 15 minutes');
select ok(not has_function_privilege('authenticated','private.invoke_photo_cleanup()','EXECUTE'),'clients cannot invoke scheduled secret function');
reset role;
update public.staff_members set active=false where user_id='53000000-0000-4000-8000-000000000001';
set local role service_role;
select throws_ok(format('select public.finalize_photo_upload(%L,%L,%L,%L)',(select j->>'id' from jobs where n=2),'53000000-0000-4000-8000-000000000001','63000000-0000-4000-8000-000000000001',(select j->>'upload_token' from jobs where n=2)),'42501','staff_required','replay rechecks membership');
reset role;
select ok(not has_function_privilege('authenticated','public.finalize_photo_upload(uuid,uuid,uuid,uuid)','EXECUTE'),'client cannot finalize');
select ok(not has_table_privilege('authenticated','public.photo_upload_jobs','UPDATE'),'client cannot change job');
select ok(not has_table_privilege('authenticated','public.animals','UPDATE'),'client cannot change primary photo');
select * from finish();rollback;
